def total_fruits(fruits):
    count = {}      # fruit type -> trees seen in window
    start = best = 0
    for i, f in enumerate(fruits):
        count[f] = count.get(f, 0) + 1
        while len(count) > 2:
            count[fruits[start]] -= 1
            if count[fruits[start]] == 0:
                del count[fruits[start]]
            start += 1
        best = max(best, i - start + 1)
    return best

