#include <bits/stdc++.h>
using namespace std;

int totalFruits(vector<int>& fruits) {
    unordered_map<int, int> count;
    int start = 0, ans = 0;
    for (int i = 0; i < (int)fruits.size(); ++i) {
        ++count[fruits[i]];
        while ((int)count.size() > 2) {
            if (--count[fruits[start]] == 0) count.erase(fruits[start]);
            ++start;
        }
        ans = max(ans, i - start + 1);
    }
    return ans;
}

